CREATE OR REPLACE STREAM ASF_PEAGE_SUIVICONSO_COMPTAGE_BOL WITH (CLEANUP_POLICY='delete', KAFKA_TOPIC='asf.peage.suiviconso.comptage.bol', KEY_FORMAT='KAFKA', PARTITIONS=6, REPLICAS=4, RETENTION_MS=604800000, VALUE_FORMAT='JSON') AS SELECT
