CREATE STREAM ASF_PEAGE_TELEOP_SYNOPTIQUE_FAV_STREAM WITH (CLEANUP_POLICY='delete', KAFKA_TOPIC='asf.peage.teleop.synoptique.fav', KEY_FORMAT='KAFKA', PARTITIONS=6, REPLICAS=4, RETENTION_MS=604800000, VALUE_FORMAT='JSON') AS SELECT
  ASF_PEAGE_VOIE_SYNOPTIQUE_STREAM.KEY KEY,
  ASF_PEAGE_VOIE_SYNOPTIQUE_STREAM.SYNOPTIQUE->DHM DHM,
  ASF_PEAGE_VOIE_SYNOPTIQUE_STREAM.SYNOPTIQUE->LOCALISATION->GARE GARE,
  ASF_PEAGE_VOIE_SYNOPTIQUE_STREAM.SYNOPTIQUE->LOCALISATION->EQUIPEMENT->NUMERO VOIE,
  1 GAREGROUP,
  (CASE WHEN ARRAY_CONTAINS(ARRAY['BE', 'BESA', 'BET'], ASF_PEAGE_VOIE_SYNOPTIQUE_STREAM.SYNOPTIQUE->LOCALISATION->EQUIPEMENT->TYPE) THEN 'E' ELSE 'S' END) ENTREESORTIE,
  (CASE WHEN ARRAY_CONTAINS(ASF_PEAGE_VOIE_SYNOPTIQUE_STREAM.ETATEQUIPEMENTS, STRUCT(SUJET:='comLS', ETAT:='comKO')) THEN 1 WHEN ARRAY_CONTAINS(ASF_PEAGE_VOIE_SYNOPTIQUE_STREAM.ETATEQUIPEMENTS, STRUCT(SUJET:='comLS', ETAT:='comOKNTR')) THEN 0 WHEN ARRAY_CONTAINS(ASF_PEAGE_VOIE_SYNOPTIQUE_STREAM.ETATEQUIPEMENTS, STRUCT(SUJET:='comLS', ETAT:='comOKTR')) THEN 0 ELSE null END) COMLSKO,
  (CASE WHEN ARRAY_CONTAINS(ASF_PEAGE_VOIE_SYNOPTIQUE_STREAM.ETATEQUIPEMENTS, STRUCT(SUJET:='contreSens', ETAT:='actif')) THEN 1 WHEN ARRAY_CONTAINS(ASF_PEAGE_VOIE_SYNOPTIQUE_STREAM.ETATEQUIPEMENTS, STRUCT(SUJET:='contreSens', ETAT:='nonActif')) THEN 0 ELSE null END) CONTRESENS,
  (CASE WHEN ARRAY_CONTAINS(ASF_PEAGE_VOIE_SYNOPTIQUE_STREAM.ETATEQUIPEMENTS, STRUCT(SUJET:='feu.affectation.flecheVerte', ETAT:='allume')) THEN 1 WHEN ARRAY_CONTAINS(ASF_PEAGE_VOIE_SYNOPTIQUE_STREAM.ETATEQUIPEMENTS, STRUCT(SUJET:='feu.affectation.flecheVerte', ETAT:='eteint')) THEN 0 ELSE null END) FAVFLECHEVERTE,
  (CASE WHEN ARRAY_CONTAINS(ASF_PEAGE_VOIE_SYNOPTIQUE_STREAM.ETATEQUIPEMENTS, STRUCT(SUJET:='feu.affectation.TIS', ETAT:='allume')) THEN 1 WHEN ARRAY_CONTAINS(ASF_PEAGE_VOIE_SYNOPTIQUE_STREAM.ETATEQUIPEMENTS, STRUCT(SUJET:='feu.affectation.TIS', ETAT:='eteint')) THEN 0 ELSE null END) FAVTIS,
  (CASE WHEN ARRAY_CONTAINS(ASF_PEAGE_VOIE_SYNOPTIQUE_STREAM.ETATEQUIPEMENTS, STRUCT(SUJET:='feu.affectation.carte', ETAT:='allume')) THEN 1 WHEN ARRAY_CONTAINS(ASF_PEAGE_VOIE_SYNOPTIQUE_STREAM.ETATEQUIPEMENTS, STRUCT(SUJET:='feu.affectation.carte', ETAT:='eteint')) THEN 0 ELSE null END) FAVCB,
  (CASE WHEN ARRAY_CONTAINS(ASF_PEAGE_VOIE_SYNOPTIQUE_STREAM.ETATEQUIPEMENTS, STRUCT(SUJET:='paiement.espece', ETAT:='accepte')) THEN 1 WHEN ARRAY_CONTAINS(ASF_PEAGE_VOIE_SYNOPTIQUE_STREAM.ETATEQUIPEMENTS, STRUCT(SUJET:='paiement.espece', ETAT:='nonAccepte')) THEN 0 ELSE null END) PAIEMENTESPECE
FROM ASF_PEAGE_VOIE_SYNOPTIQUE_STREAM ASF_PEAGE_VOIE_SYNOPTIQUE_STREAM
WHERE ((NOT ARRAY_CONTAINS(ARRAY['BECM', 'VSP'], ASF_PEAGE_VOIE_SYNOPTIQUE_STREAM.SYNOPTIQUE->LOCALISATION->EQUIPEMENT->TYPE)) AND ((((((((((((ARRAY_CONTAINS(ASF_PEAGE_VOIE_SYNOPTIQUE_STREAM.ETATEQUIPEMENTS, STRUCT(SUJET:='comLS', ETAT:='comKO')) OR ARRAY_CONTAINS(ASF_PEAGE_VOIE_SYNOPTIQUE_STREAM.ETATEQUIPEMENTS, STRUCT(SUJET:='comLS', ETAT:='comOKNTR'))) OR ARRAY_CONTAINS(ASF_PEAGE_VOIE_SYNOPTIQUE_STREAM.ETATEQUIPEMENTS, STRUCT(SUJET:='comLS', ETAT:='comOKTR'))) OR ARRAY_CONTAINS(ASF_PEAGE_VOIE_SYNOPTIQUE_STREAM.ETATEQUIPEMENTS, STRUCT(SUJET:='contreSens', ETAT:='actif'))) OR ARRAY_CONTAINS(ASF_PEAGE_VOIE_SYNOPTIQUE_STREAM.ETATEQUIPEMENTS, STRUCT(SUJET:='contreSens', ETAT:='nonActif'))) OR ARRAY_CONTAINS(ASF_PEAGE_VOIE_SYNOPTIQUE_STREAM.ETATEQUIPEMENTS, STRUCT(SUJET:='feu.affectation.flecheVerte', ETAT:='allume'))) OR ARRAY_CONTAINS(ASF_PEAGE_VOIE_SYNOPTIQUE_STREAM.ETATEQUIPEMENTS, STRUCT(SUJET:='feu.affectation.flecheVerte', ETAT:='eteint'))) OR ARRAY_CONTAINS(ASF_PEAGE_VOIE_SYNOPTIQUE_STREAM.ETATEQUIPEMENTS, STRUCT(SUJET:='feu.affectation.TIS', ETAT:='allume'))) OR ARRAY_CONTAINS(ASF_PEAGE_VOIE_SYNOPTIQUE_STREAM.ETATEQUIPEMENTS, STRUCT(SUJET:='feu.affectation.TIS', ETAT:='eteint'))) OR ARRAY_CONTAINS(ASF_PEAGE_VOIE_SYNOPTIQUE_STREAM.ETATEQUIPEMENTS, STRUCT(SUJET:='feu.affectation.carte', ETAT:='allume'))) OR ARRAY_CONTAINS(ASF_PEAGE_VOIE_SYNOPTIQUE_STREAM.ETATEQUIPEMENTS, STRUCT(SUJET:='feu.affectation.carte', ETAT:='eteint'))) OR ARRAY_CONTAINS(ASF_PEAGE_VOIE_SYNOPTIQUE_STREAM.ETATEQUIPEMENTS, STRUCT(SUJET:='paiement.espece', ETAT:='accepte'))) OR ARRAY_CONTAINS(ASF_PEAGE_VOIE_SYNOPTIQUE_STREAM.ETATEQUIPEMENTS, STRUCT(SUJET:='paiement.espece', ETAT:='nonAccepte'))))
PARTITION BY ASF_PEAGE_VOIE_SYNOPTIQUE_STREAM.KEY
EMIT CHANGES;

CREATE STREAM ESC_PEAGE_TELEOP_SYNOPTIQUE_FAV_STREAM WITH (CLEANUP_POLICY='delete', KAFKA_TOPIC='esc.peage.teleop.synoptique.fav', KEY_FORMAT='KAFKA', PARTITIONS=6, REPLICAS=4, RETENTION_MS=864000000, VALUE_FORMAT='JSON') AS SELECT
  ESC_PEAGE_VOIE_SYNOPTIQUE_STREAM.KEY KEY,
  ESC_PEAGE_VOIE_SYNOPTIQUE_STREAM.SYNOPTIQUE->DHM DHM,
  ESC_PEAGE_VOIE_SYNOPTIQUE_STREAM.SYNOPTIQUE->LOCALISATION->GARE GARE,
  ESC_PEAGE_VOIE_SYNOPTIQUE_STREAM.SYNOPTIQUE->LOCALISATION->EQUIPEMENT->NUMERO VOIE,
  (CASE WHEN ARRAY_CONTAINS(ARRAY['25006001', '25006014', '25006010', '25006011', '25006012', '25006013', '25006016', '25006017', '25006019', '25006020', '25006021', '25006024', '25006025', '25006026', '25006027', '25006028', '25006029', '25006031', '25006032', '25006033', '25006034', '25006035', '25006054', '25006056', '25006097'], ESC_PEAGE_VOIE_SYNOPTIQUE_STREAM.SYNOPTIQUE->LOCALISATION->GARE) THEN (CASE WHEN (CAST(ESC_PEAGE_VOIE_SYNOPTIQUE_STREAM.SYNOPTIQUE->LOCALISATION->EQUIPEMENT->NUMERO AS INTEGER) < 20) THEN 1 ELSE 2 END) ELSE 1 END) GAREGROUP,
  (CASE WHEN ARRAY_CONTAINS(ARRAY['BE', 'BESA', 'BET', 'BE ESCOTA'], ESC_PEAGE_VOIE_SYNOPTIQUE_STREAM.SYNOPTIQUE->LOCALISATION->EQUIPEMENT->TYPE) THEN 'E' ELSE 'S' END) ENTREESORTIE,
  (CASE WHEN ARRAY_CONTAINS(ESC_PEAGE_VOIE_SYNOPTIQUE_STREAM.ETATEQUIPEMENTS, STRUCT(SUJET:='comLS', ETAT:='comKO')) THEN 1 WHEN ARRAY_CONTAINS(ESC_PEAGE_VOIE_SYNOPTIQUE_STREAM.ETATEQUIPEMENTS, STRUCT(SUJET:='comLS', ETAT:='comOKNTR')) THEN 0 WHEN ARRAY_CONTAINS(ESC_PEAGE_VOIE_SYNOPTIQUE_STREAM.ETATEQUIPEMENTS, STRUCT(SUJET:='comLS', ETAT:='comOKTR')) THEN 0 ELSE null END) COMLSKO,
  (CASE WHEN ARRAY_CONTAINS(ESC_PEAGE_VOIE_SYNOPTIQUE_STREAM.ETATEQUIPEMENTS, STRUCT(SUJET:='contreSens', ETAT:='actif')) THEN 1 WHEN ARRAY_CONTAINS(ESC_PEAGE_VOIE_SYNOPTIQUE_STREAM.ETATEQUIPEMENTS, STRUCT(SUJET:='contreSens', ETAT:='nonActif')) THEN 0 ELSE null END) CONTRESENS,
  (CASE WHEN ARRAY_CONTAINS(ESC_PEAGE_VOIE_SYNOPTIQUE_STREAM.ETATEQUIPEMENTS, STRUCT(SUJET:='feu.affectation.flecheVerte', ETAT:='allume')) THEN 1 WHEN ARRAY_CONTAINS(ESC_PEAGE_VOIE_SYNOPTIQUE_STREAM.ETATEQUIPEMENTS, STRUCT(SUJET:='feu.affectation.flecheVerte', ETAT:='eteint')) THEN 0 ELSE null END) FAVFLECHEVERTE,
  (CASE WHEN ARRAY_CONTAINS(ESC_PEAGE_VOIE_SYNOPTIQUE_STREAM.ETATEQUIPEMENTS, STRUCT(SUJET:='feu.affectation.TIS', ETAT:='allume')) THEN 1 WHEN ARRAY_CONTAINS(ESC_PEAGE_VOIE_SYNOPTIQUE_STREAM.ETATEQUIPEMENTS, STRUCT(SUJET:='feu.affectation.TIS', ETAT:='eteint')) THEN 0 ELSE null END) FAVTIS,
  (CASE WHEN ARRAY_CONTAINS(ESC_PEAGE_VOIE_SYNOPTIQUE_STREAM.ETATEQUIPEMENTS, STRUCT(SUJET:='feu.affectation.carte', ETAT:='allume')) THEN 1 WHEN ARRAY_CONTAINS(ESC_PEAGE_VOIE_SYNOPTIQUE_STREAM.ETATEQUIPEMENTS, STRUCT(SUJET:='feu.affectation.carte', ETAT:='eteint')) THEN 0 ELSE null END) FAVCB,
  (CASE WHEN ARRAY_CONTAINS(ESC_PEAGE_VOIE_SYNOPTIQUE_STREAM.ETATEQUIPEMENTS, STRUCT(SUJET:='paiement.espece', ETAT:='accepte')) THEN 1 WHEN ARRAY_CONTAINS(ESC_PEAGE_VOIE_SYNOPTIQUE_STREAM.ETATEQUIPEMENTS, STRUCT(SUJET:='paiement.espece', ETAT:='nonAccepte')) THEN 0 ELSE null END) PAIEMENTESPECE
FROM ESC_PEAGE_VOIE_SYNOPTIQUE_STREAM ESC_PEAGE_VOIE_SYNOPTIQUE_STREAM
WHERE ((((((((((((ARRAY_CONTAINS(ESC_PEAGE_VOIE_SYNOPTIQUE_STREAM.ETATEQUIPEMENTS, STRUCT(SUJET:='comLS', ETAT:='comKO')) OR ARRAY_CONTAINS(ESC_PEAGE_VOIE_SYNOPTIQUE_STREAM.ETATEQUIPEMENTS, STRUCT(SUJET:='comLS', ETAT:='comOKNTR'))) OR ARRAY_CONTAINS(ESC_PEAGE_VOIE_SYNOPTIQUE_STREAM.ETATEQUIPEMENTS, STRUCT(SUJET:='comLS', ETAT:='comOKTR'))) OR ARRAY_CONTAINS(ESC_PEAGE_VOIE_SYNOPTIQUE_STREAM.ETATEQUIPEMENTS, STRUCT(SUJET:='contreSens', ETAT:='actif'))) OR ARRAY_CONTAINS(ESC_PEAGE_VOIE_SYNOPTIQUE_STREAM.ETATEQUIPEMENTS, STRUCT(SUJET:='contreSens', ETAT:='nonActif'))) OR ARRAY_CONTAINS(ESC_PEAGE_VOIE_SYNOPTIQUE_STREAM.ETATEQUIPEMENTS, STRUCT(SUJET:='feu.affectation.flecheVerte', ETAT:='allume'))) OR ARRAY_CONTAINS(ESC_PEAGE_VOIE_SYNOPTIQUE_STREAM.ETATEQUIPEMENTS, STRUCT(SUJET:='feu.affectation.flecheVerte', ETAT:='eteint'))) OR ARRAY_CONTAINS(ESC_PEAGE_VOIE_SYNOPTIQUE_STREAM.ETATEQUIPEMENTS, STRUCT(SUJET:='feu.affectation.TIS', ETAT:='allume'))) OR ARRAY_CONTAINS(ESC_PEAGE_VOIE_SYNOPTIQUE_STREAM.ETATEQUIPEMENTS, STRUCT(SUJET:='feu.affectation.TIS', ETAT:='eteint'))) OR ARRAY_CONTAINS(ESC_PEAGE_VOIE_SYNOPTIQUE_STREAM.ETATEQUIPEMENTS, STRUCT(SUJET:='feu.affectation.carte', ETAT:='allume'))) OR ARRAY_CONTAINS(ESC_PEAGE_VOIE_SYNOPTIQUE_STREAM.ETATEQUIPEMENTS, STRUCT(SUJET:='feu.affectation.carte', ETAT:='eteint'))) OR ARRAY_CONTAINS(ESC_PEAGE_VOIE_SYNOPTIQUE_STREAM.ETATEQUIPEMENTS, STRUCT(SUJET:='paiement.espece', ETAT:='accepte'))) OR ARRAY_CONTAINS(ESC_PEAGE_VOIE_SYNOPTIQUE_STREAM.ETATEQUIPEMENTS, STRUCT(SUJET:='paiement.espece', ETAT:='nonAccepte')))
PARTITION BY ESC_PEAGE_VOIE_SYNOPTIQUE_STREAM.KEY
